import 'json_io.dart';

/// The credit that the records' licenses require, as Markdown.
String attributionOf(List<Json> records, List<Json> sources) {
  final credited = [
    for (final r in records)
      if (r['credit'] != null) r,
  ];
  final b = StringBuffer()
    ..writeln('# Attribution')
    ..writeln()
    ..writeln(
      'This file is generated by `make build`. The dataset is under '
      'CC BY-SA 4.0, and it uses these sources:',
    )
    ..writeln();
  for (final s in sources) {
    b.writeln(
      '- ${s['dataset']} (${s['url']}), by '
      '${(s['authors'] as List).join(', ')}, under ${s['license']}.',
    );
  }
  b
    ..writeln()
    ..writeln('## Records that require credit')
    ..writeln();
  if (credited.isEmpty) {
    b.writeln('No record requires credit.');
  }
  for (final r in credited) {
    final c = r['credit'] as Json;
    b.writeln(
      '- ${r['name']} (`${r['slug']}`): from ${c['dataset']}, by '
      '${(c['authors'] as List).join(', ')}, under ${c['license']}. '
      '${c['url']}',
    );
  }
  return b.toString();
}
